import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.CShDTZbC.js";const s="/assets/image.C6z9plj6.png",i="/assets/image-1.C-xoFvpP.png",n="/assets/image-2.Bc7zVpxk.png",d="/assets/image-3.BjEGuTrJ.png",l="/assets/image-4.mrosCaIO.png",c="/assets/image-10.CnReboQ1.png",h="/assets/image-11.D35FnnVB.png",g="/assets/image-12.Vr-bYxge.png",p="/assets/image-13.C0JfkOCg.png",u="/assets/image-8.B-DwzSvF.png",b="/assets/image-9.BL5FpVAy.png",m="/assets/image-5.DokG79nb.png",f="/assets/image-6.DfGqZzO5.png",v="/assets/image-7.CRBi1D3m.png",T=JSON.parse('{"title":"STEMSpark4Kids User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),w={name:"index.md"};function k(P,e,y,x,q,S){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="STEMSpark4Kids-user-guide" tabindex="-1">STEMSpark4Kids User Guide <a class="header-anchor" href="#STEMSpark4Kids-user-guide" aria-label="Permalink to &quot;STEMSpark4Kids User Guide&quot;">​</a></h1><p>This page documents the user-facing functionality currently implemented in STEMSpark4Kids. Screens that require authentication redirect visitors to <code>/login</code>. Role-restricted screens redirect users without the required role back to <code>/dashboard</code>.</p><h2 id="navigation-and-access" tabindex="-1">Navigation and access <a class="header-anchor" href="#navigation-and-access" aria-label="Permalink to &quot;Navigation and access&quot;">​</a></h2><p>The shared application layout provides the main navigation and footer. The <code>/dashboard</code> route is a role router: after authentication it sends users to the dashboard for their role.</p><table tabindex="0"><thead><tr><th>Route</th><th>Page</th><th>Access</th></tr></thead><tbody><tr><td><code>/</code></td><td>Landing</td><td>Public</td></tr><tr><td><code>/login</code></td><td>Login</td><td>Public</td></tr><tr><td><code>/register</code></td><td>Registration</td><td>Public</td></tr><tr><td><code>/onboarding</code></td><td>Role selection</td><td>Signed-in users</td></tr><tr><td><code>/dashboard</code></td><td>Dashboard redirect</td><td>Signed-in users</td></tr><tr><td><code>/student</code></td><td>Student dashboard</td><td>Students</td></tr><tr><td><code>/parent</code></td><td>Parent dashboard</td><td>Parents</td></tr><tr><td><code>/teacher</code></td><td>Teacher dashboard</td><td>Teachers</td></tr></tbody></table><p>| <code>/subject/:subjectId</code> | Subject activities | Signed-in users | | <code>/activity/:subjectId/:activityId</code> | Activity player | Signed-in users | | <code>/ai-worksheet</code> | AI worksheet generator | All signed-in roles | | <code>/leaderboard</code> | Weekly leaderboard | Signed-in users | | <code>/progress</code> | Progress reports | Signed-in users |</p><h2 id="public-pages" tabindex="-1">Public pages <a class="header-anchor" href="#public-pages" aria-label="Permalink to &quot;Public pages&quot;">​</a></h2><h3 id="landing-page" tabindex="-1">Landing page: <code>/</code> <a class="header-anchor" href="#landing-page" aria-label="Permalink to &quot;Landing page: `/`&quot;">​</a></h3><p>The landing page introduces STEMSpark4Kids and gives visitors three entry points:</p><ul><li><strong>Start Free</strong> opens registration.</li><li><strong>Parent Login</strong> opens login with the parent role suggested.</li><li><strong>Teacher Login</strong> opens login with the teacher role suggested.</li></ul><p>Visitors can also select a subject card to open that subject after signing in. The page displays supported grades from Pre-K through Grade 5, the subject catalog, product features, and testimonials.</p><h3 id="registration-register" tabindex="-1">Registration: <code>/register</code> <a class="header-anchor" href="#registration-register" aria-label="Permalink to &quot;Registration: `/register`&quot;">​</a></h3><ol><li>Choose a role: student, parent, or teacher.</li><li>If registering as a student, choose a grade from Pre-K through Grade 5.</li><li>Enter a name, email, and password of at least six characters.</li><li>Submit the form or use Google sign-up when Google authentication is configured.</li></ol><p>Successful registration sends the user to <code>/dashboard</code>. Registration errors appear as toast notifications.</p><h3 id="login-login" tabindex="-1">Login: <code>/login</code> <a class="header-anchor" href="#login-login" aria-label="Permalink to &quot;Login: `/login`&quot;">​</a></h3><p>Users can sign in with email and password or Google. A successful login sends the user to <code>/dashboard</code>, which chooses the correct role dashboard. The page accepts an optional role query parameter, for example <code>/login?role=parent</code>, to show the suggested role in the form.</p><p>Google login requires <code>REACT_APP_GOOGLE_CLIENT_ID</code> in <code>frontend/.env</code>. Without it, the page shows a configuration message instead of the Google button. <img src="'+s+'" alt="alt text"></p><h3 id="authentication-callback" tabindex="-1">Authentication callback <a class="header-anchor" href="#authentication-callback" aria-label="Permalink to &quot;Authentication callback&quot;">​</a></h3><p>When an external authentication flow returns with a <code>session_id</code> hash, STEMSpark4Kids exchanges it with the backend, stores the returned session token, updates the user, removes the hash from the URL, and redirects to the dashboard. Failed exchanges return the user to login.</p><h2 id="onboarding-and-dashboards" tabindex="-1">Onboarding and dashboards <a class="header-anchor" href="#onboarding-and-dashboards" aria-label="Permalink to &quot;Onboarding and dashboards&quot;">​</a></h2><h3 id="role-selection-onboarding" tabindex="-1">Role selection: <code>/onboarding</code> <a class="header-anchor" href="#role-selection-onboarding" aria-label="Permalink to &quot;Role selection: `/onboarding`&quot;">​</a></h3><p>Signed-in users can choose student, parent, or teacher. Students can also select a grade. <strong>Continue</strong> saves the profile through the backend and returns to the role dashboard.</p><h3 id="student-dashboard-student" tabindex="-1">Student dashboard: <code>/student</code> <a class="header-anchor" href="#student-dashboard-student" aria-label="Permalink to &quot;Student dashboard: `/student`&quot;">​</a></h3><p>The student dashboard is the main learning home:</p><ul><li>Shows the learner greeting, grade, XP, coins, and day streak.</li><li>Shows earned and locked badges.</li><li>Provides a four-step daily path with an estimated 30-minute duration. Selecting a step opens its activity.</li><li>Lists all available subjects. Selecting a subject opens its activity catalog.</li><li>Shows recent completed activities with score, stars, and XP when progress exists.</li><li>Links to the full progress report through <strong>See all progress</strong>. <img src="'+i+'" alt="alt text"></li></ul><h3 id="parent-dashboard-parent" tabindex="-1">Parent dashboard: <code>/parent</code> <a class="header-anchor" href="#parent-dashboard-parent" aria-label="Permalink to &quot;Parent dashboard: `/parent`&quot;">​</a></h3><p>Parents can:</p><ol><li>Enter a child’s registered email and choose <strong>Link Child</strong>.</li><li>Review linked children, grade, XP, and streak.</li><li>Choose <strong>View Progress</strong> to load the child’s ten most recent completions, including date, subject, activity, and score.</li><li>Close the child detail panel.</li><li>Open the AI Worksheet Generator.</li></ol><p>The child must have an existing student account before linking. <img src="'+n+'" alt="alt text"></p><h3 id="teacher-dashboard-teacher" tabindex="-1">Teacher dashboard: <code>/teacher</code> <a class="header-anchor" href="#teacher-dashboard-teacher" aria-label="Permalink to &quot;Teacher dashboard: `/teacher`&quot;">​</a></h3><p>Teachers manage classrooms and assignments:</p><ol><li>Choose <strong>New Classroom</strong>.</li><li>Enter a classroom name, grade, and optional description.</li><li>Open a classroom to view students and assignments.</li><li>Copy the classroom join code to share with students.</li><li>Create an assignment with a title, subject, activity, optional due date, and optional target student.</li><li>Review assignments shown for the class and for individual students.</li></ol><p>Teachers can also open the AI Worksheet Generator from the dashboard.</p><p><img src="'+d+'" alt="alt text"></p><p><img src="'+l+'" alt="alt text"></p><h2 id="learning-catalog" tabindex="-1">Learning catalog <a class="header-anchor" href="#learning-catalog" aria-label="Permalink to &quot;Learning catalog&quot;">​</a></h2><h3 id="subject-view-subject-subjectid" tabindex="-1">Subject view: <code>/subject/:subjectId</code> <a class="header-anchor" href="#subject-view-subject-subjectid" aria-label="Permalink to &quot;Subject view: `/subject/:subjectId`&quot;">​</a></h3><p>Subject pages show the subject tagline, topic badges, and available activity cards. Each activity card displays its type, difficulty, title, and topic. Choose <strong>Start</strong> to open the activity player. Use <strong>Back</strong> to return to the previous page.</p><p>The current subjects are:</p><table tabindex="0"><thead><tr><th>Subject</th><th>Topics</th><th>Activity types currently available</th></tr></thead><tbody><tr><td>Math Adventures</td><td>Counting, addition, subtraction, shapes, patterns, multiplication, fractions</td><td>Quiz, flashcards</td></tr><tr><td>Science Lab</td><td>Plants, animals, human body, weather, space, water cycle</td><td>Quiz, flashcards</td></tr><tr><td>Tech &amp; Coding</td><td>Computer basics, typing, AI basics, Scratch, digital safety</td><td>Quiz</td></tr><tr><td>Engineering</td><td>Simple machines, bridges, physics, design thinking, problem solving</td><td>Flashcards</td></tr><tr><td>Reading &amp; Words</td><td>Phonics, sight words, comprehension, vocabulary, spelling</td><td>Quiz, flashcards</td></tr><tr><td>Letter Tracing</td><td>Uppercase/lowercase letters, numbers, shapes, words</td><td>Tracing</td></tr><tr><td>Coloring Fun</td><td>Animals, dinosaurs, space, alphabet, robots</td><td>Coloring</td></tr></tbody></table><p>Subjects without activities show a <strong>Coming soon</strong> state.</p><h3 id="quiz-activities" tabindex="-1">Quiz activities <a class="header-anchor" href="#quiz-activities" aria-label="Permalink to &quot;Quiz activities&quot;">​</a></h3><ol><li>Read the question and choose one answer.</li><li>The selected answer is immediately marked correct or incorrect.</li><li>Choose <strong>Next</strong> to continue, or <strong>Finish</strong> on the final question.</li><li>On completion, the app records the score and time, refreshes the user profile, and shows XP, coins, and stars.</li><li>Choose <strong>Try Again</strong> to restart or <strong>Back</strong> to return to the subject.</li></ol><p><img src="'+c+'" alt="alt text"></p><p><img src="'+h+'" alt="alt text"></p><p><img src="'+g+'" alt="alt text"></p><h3 id="flashcard-activities" tabindex="-1">Flashcard activities <a class="header-anchor" href="#flashcard-activities" aria-label="Permalink to &quot;Flashcard activities&quot;">​</a></h3><ul><li>Select the card to reveal its answer.</li><li>Use <strong>Prev</strong> and <strong>Next</strong> to move through cards.</li><li>Choose <strong>I know this</strong> to mark the current card as known and advance.</li><li>Choose <strong>Finish</strong> on the final card to record completion.</li><li>The result modal offers <strong>Try Again</strong> and <strong>Back</strong>. <img src="'+p+'" alt="alt text"></li></ul><h3 id="coloring-activities" tabindex="-1">Coloring activities <a class="header-anchor" href="#coloring-activities" aria-label="Permalink to &quot;Coloring activities&quot;">​</a></h3><p>Coloring activities provide a canvas with an optional template. Users can:</p><ul><li>Select a color from the palette.</li><li>Select one of four brush sizes.</li><li>Draw with mouse or touch input.</li><li>Use <strong>Undo</strong>, <strong>Clear</strong>, and <strong>Save</strong> to download a PNG.</li><li>Choose <strong>Done</strong> to record completion based on drawing effort.</li></ul><p><img src="'+u+'" alt="alt text"></p><h3 id="tracing-activities" tabindex="-1">Tracing activities <a class="header-anchor" href="#tracing-activities" aria-label="Permalink to &quot;Tracing activities&quot;">​</a></h3><p>Tracing activities show a ghost character or letter over a canvas:</p><ul><li>Choose <strong>Hear it</strong> to read the current character aloud when browser speech synthesis is available.</li><li>Trace using mouse or touch input.</li><li>Choose <strong>Try again</strong> to clear the current canvas.</li><li>Choose <strong>Next Letter</strong> to continue, or <strong>Finish</strong> on the last character.</li></ul><p>Tracing completion records the activity and opens the standard result modal.</p><p><img src="'+b+'" alt="alt text"></p><h3 id="completion-results" tabindex="-1">Completion results <a class="header-anchor" href="#completion-results" aria-label="Permalink to &quot;Completion results&quot;">​</a></h3><p>Completed activities display a result modal with a message, one to three stars, XP earned, and coins earned. Two actions are available: restart the activity or return to the subject/student area. Results with at least two stars also trigger celebratory confetti.</p><h2 id="progress-and-motivation" tabindex="-1">Progress and motivation <a class="header-anchor" href="#progress-and-motivation" aria-label="Permalink to &quot;Progress and motivation&quot;">​</a></h2><h3 id="progress-report-progress" tabindex="-1">Progress report: <code>/progress</code> <a class="header-anchor" href="#progress-report-progress" aria-label="Permalink to &quot;Progress report: `/progress`&quot;">​</a></h3><p>The progress page displays:</p><ul><li>XP earned, coins, day streak, and total activities.</li><li>A weekly activity bar chart.</li><li>A by-subject completion chart.</li><li>A recent activity table with date, subject, activity, score, and stars.</li></ul><p>Empty accounts show guidance to start learning instead of charts or rows.</p><h3 id="leaderboard-leaderboard" tabindex="-1">Leaderboard: <code>/leaderboard</code> <a class="header-anchor" href="#leaderboard-leaderboard" aria-label="Permalink to &quot;Leaderboard: `/leaderboard`&quot;">​</a></h3><p>The leaderboard loads weekly learners from the backend and shows rank, avatar or initial, name, grade, and XP. The signed-in user’s row is highlighted and labeled <strong>you</strong>. Empty results show a first-learner message.</p><h2 id="ai-worksheet-generator-ai-worksheet" tabindex="-1">AI Worksheet Generator: <code>/ai-worksheet</code> <a class="header-anchor" href="#ai-worksheet-generator-ai-worksheet" aria-label="Permalink to &quot;AI Worksheet Generator: `/ai-worksheet`&quot;">​</a></h2><p>The worksheet generator is available to every authenticated role:</p><ol><li>Choose a subject.</li><li>Enter a topic.</li><li>Choose a grade.</li><li>Choose easy, medium, or hard difficulty.</li><li>Set the number of questions from 3 to 15.</li><li>Choose <strong>Generate</strong>.</li></ol><p>The generated worksheet includes instructions, name/date fields, questions, and hints. <strong>Show Answers</strong> toggles answer visibility. <strong>Print / PDF</strong> opens the browser print flow, where the worksheet can be printed or saved as a PDF. Recent worksheets appear in the history list and can be reopened.</p><p><img src="'+m+'" alt="alt text"></p><p><img src="'+f+'" alt="alt text"></p><p><img src="'+v+'" alt="alt text"></p>',73)])])}const C=t(w,[["render",k]]);export{T as __pageData,C as default};
